class Solution:
    def splitMessage(self, message: str, limit: int) -> List[str]:
        n = len(message)

        def digits(x):
            return len(str(x))

        for b in range(1, n + 1):
            db = digits(b)
            if limit - 3 - db - db <= 0:
                continue
            cap = 0
            for a in range(1, b + 1):
                cap += limit - 3 - digits(a) - db
            if cap < n:
                continue
            res = []
            i = 0
            for a in range(1, b + 1):
                sz = limit - 3 - digits(a) - db
                res.append(message[i:i + sz] + "<" + str(a) + "/" + str(b) + ">")
                i += sz
            return res
        return []

