class Solution {
public:
    vector<string> splitMessage(string message, int limit) {
        int n = message.size();
        auto digs = [](int x){ return (int)to_string(x).size(); };
        for (int b = 1; b <= n; b++) {
            int db = digs(b);
            if (limit - 3 - 2 * db <= 0) continue;
            long long cap = 0;
            for (int a = 1; a <= b; a++) cap += limit - 3 - digs(a) - db;
            if (cap < n) continue;
            vector<string> res;
            int i = 0;
            for (int a = 1; a <= b; a++) {
                int sz = limit - 3 - digs(a) - db;
                res.push_back(message.substr(i, sz) + "<" + to_string(a) + "/" + to_string(b) + ">");
                i += sz;
            }
            return res;
        }
        return {};
    }
};

