class Solution {
    public String[] splitMessage(String message, int limit) {
        int n = message.length();
        for (int b = 1; b <= n; b++) {
            int db = Integer.toString(b).length();
            if (limit - 3 - 2 * db <= 0) continue;
            long cap = 0;
            for (int a = 1; a <= b; a++) cap += limit - 3 - Integer.toString(a).length() - db;
            if (cap < n) continue;
            String[] res = new String[b];
            int i = 0;
            for (int a = 1; a <= b; a++) {
                int sz = limit - 3 - Integer.toString(a).length() - db;
                res[a - 1] = message.substring(i, Math.min(i + sz, n)) + "<" + a + "/" + b + ">";
                i += sz;
            }
            return res;
        }
        return new String[0];
    }
}

